using System;
using System.Linq;
using UnityEngine;
// Run runtime checks in Play mode with desktop XR disabled; Android tracking is unaffected.
public static class StarePresenceChecks
{
public static string Rules()
{
int n=0;System.Action<bool,string> check=(ok,label)=>{if(!ok)throw new System.Exception(label);n++;};
var frame=new Staredown.StarePresenceFrame{headTracked=true,head=Quaternion.Euler(20,30,0),mouth=.7f,left=new Staredown.StareHandPose{tracked=true,position=new Vector3(-.3f,-.4f,.4f),rotation=Quaternion.identity,grip=.5f}};
var safe=Staredown.StarePresenceValidation.Sanitize(frame);check(safe.left.tracked&&safe.headTracked&&Mathf.Abs(safe.mouth-.7f)<.001f,"Valid tracked pose survives");frame.left.position=new Vector3(float.NaN,0,0);frame.mouth=float.NaN;safe=Staredown.StarePresenceValidation.Sanitize(frame);check(!safe.left.tracked&&safe.mouth==0,"Invalid floats rejected");frame.left.position=Vector3.one*3;safe=Staredown.StarePresenceValidation.Sanitize(frame);check(!safe.left.tracked,"Outlier hand rejected");frame.head=new Quaternion();check(!Staredown.StarePresenceValidation.Sanitize(frame).headTracked,"Zero quaternion rejected");
check(Staredown.StareVoice.SpeechOpening(0,false)==0&&Staredown.StareVoice.SpeechOpening(double.NaN,true)==0,"Silence and invalid energy close mouth");check(Staredown.StareVoice.SpeechOpening(2,true)==1,"Speech opening bounded");
var t=new Staredown.Tournament();t.Add(0,"HOST");t.EnableBotFill();check(t.Presence(0,safe)&&!t.Presence(1000,safe),"Only human presence accepted");t.Input(0,.25f,.75f,true,true,0,0,0);check(t.Find(0).left==.25f&&t.Find(0).right==.75f,"Independent continuous eyelids");var wire=JsonUtility.ToJson(new Staredown.WireMessage{kind="state",state=t.Snapshot()});check(System.Text.Encoding.UTF8.GetByteCount(wire)<65536,"Twenty contestant snapshot fits network frame");var copy=JsonUtility.FromJson<Staredown.WireMessage>(wire);check(copy.state.fighters[0].left==.25f&&copy.state.fighters[0].presence.headTracked==safe.headTracked,"Presence and eyelids serialize");t.Input(0,0,0,true,true,0,0,0);check(t.Start(),"Start");t.Find(0).alive=false;check(!t.RoomPose(0,Staredown.ArenaLayout.Seat(t.Snapshot(),t.Fighters.First(f=>f.alive).id),0),"Spectator cannot enter competitor field");check(!t.RoomPose(0,new Vector3(14,0,0),0),"Wrong spectator floor rejected");check(t.RoomPose(0,new Vector3(0,0,-12),90),"Spectator arena pose accepted");check(Staredown.StareSpectatorArea.Contains(Staredown.StareSpectatorArea.Clamp(Vector3.zero)),"Zero pose clamps onto seating");check(Staredown.StareSpectatorArea.Contains(Staredown.StareSpectatorArea.Clamp(Vector3.one*30)),"Far pose clamps onto seating");t.Remove(0);check(!t.Presence(0,safe),"Disconnected presence rejected");
return n+" presence rules checks passed; "+StareBuild.VerifyMixedRoster()+"; "+StareBuild.VerifyMixedRosterNetwork()+"; "+StareBuild.Verify();
}
public static string Transport()
{
var host=new Staredown.StareNetwork();var guest=new Staredown.StareNetwork();var tournament=new Staredown.Tournament();tournament.Add(0,"HOST");int received=0;try{host.Host();guest.Join("127.0.0.1");var timer=System.Diagnostics.Stopwatch.StartNew();while(timer.ElapsedMilliseconds<5000&&received<2){Staredown.StareNetwork.Incoming packet;while(host.Poll(out packet)){var m=JsonUtility.FromJson<Staredown.WireMessage>(packet.json);if(m.kind=="connected"){tournament.Add(packet.sender,"GUEST");host.Send(packet.sender,new Staredown.WireMessage{kind="welcome",id=packet.sender});}else if(m.kind=="input"){if(m.id==packet.sender)throw new System.Exception("Spoof fixture is invalid");tournament.Input(packet.sender,m.left,m.right,true,true,0,0,0);tournament.Presence(packet.sender,m.presence);host.Broadcast(new Staredown.WireMessage{kind="state",state=tournament.Snapshot()});received++;}}while(guest.Poll(out packet)){var m=JsonUtility.FromJson<Staredown.WireMessage>(packet.json);if(m.kind=="welcome")guest.Send(0,new Staredown.WireMessage{kind="input",id=9000,left=.3f,right=.8f,presence=new Staredown.StarePresenceFrame{mouth=.6f,headTracked=true,head=Quaternion.Euler(0,35,0),left=new Staredown.StareHandPose{tracked=true,position=new Vector3(-.3f,-.2f,.4f),rotation=Quaternion.identity}}});else if(m.kind=="state"){var f=m.state.fighters.First(x=>x.id!=0);if(f.id==9000||!f.presence.left.tracked||Mathf.Abs(f.presence.left.position.z-.4f)>.001f||f.presence.mouth!=.6f||f.left!=.3f||f.right!=.8f)throw new System.Exception("Tracked pose/face transport mismatch");received++;}}System.Threading.Thread.Sleep(10);}if(received!=2)throw new System.Exception("Presence transport timeout");return "Authenticated hand/head/mouth and independent eyelids round-trip through real LAN sockets";}finally{guest.Dispose();host.Dispose();}
}
public static string Attachments()
{
var view=UnityEngine.Object.FindFirstObjectByType<Staredown.StareVisuals>();var fixture=new GameObject("Attachment motion checks");int n=0;try{for(int kind=5;kind<=8;kind++){var a=view.CreateAvatar(kind,null,fixture.transform);var animator=a.preset.GetComponent<Animator>();animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();var head=a.preset.GetComponentsInChildren<Transform>().First(x=>x.name=="head");var chest=a.preset.GetComponentsInChildren<Transform>().First(x=>x.name=="chest");foreach(var lod in a.preset.GetComponent<LODGroup>().GetLODs())foreach(var renderer in lod.renderers){if(!renderer.name.Contains("Helmet")&&!renderer.name.Contains("Hat")&&!renderer.name.Contains("Cape"))continue;var skin=renderer as SkinnedMeshRenderer;var anchor=renderer.name.Contains("Cape")?chest:head;if(skin==null||!skin.bones.Contains(anchor))throw new System.Exception("Attachment is bound to an inactive skeleton: "+renderer.name);Vector3 start=Vector3.zero;for(int pose=0;pose<8;pose++){animator.Play("Dance",0,pose/8f);animator.Update(.01f);var w=skin.sharedMesh.boneWeights[0];var v=skin.sharedMesh.vertices[0];var world=skin.bones[w.boneIndex0].localToWorldMatrix.MultiplyPoint3x4(skin.sharedMesh.bindposes[w.boneIndex0].MultiplyPoint3x4(v));var point=anchor.InverseTransformPoint(world);if(pose==0)start=point;else if((point-start).magnitude>.003f)throw new System.Exception("Attachment drift: "+renderer.name);}n++;}}var balcony=view.GetComponentsInChildren<MeshCollider>(true).FirstOrDefault(x=>x.name.Contains("Spectator"));if(balcony==null)throw new System.Exception("Spectator walkway collider missing");RaycastHit hit;if(!balcony.Raycast(new Ray(new Vector3(14,4,0),Vector3.down),out hit,8)||Mathf.Abs(hit.point.y-Staredown.StareSpectatorArea.Floor)>.03f)throw new System.Exception("Spectator floor height mismatch");n++;return n+" attachment dance and seating floor checks passed";}finally{UnityEngine.Object.Destroy(fixture);}
}
public static string Runtime(string imagePath)
{
var view=UnityEngine.Object.FindFirstObjectByType<Staredown.StareVisuals>();var fixture=new GameObject("Presence verification");int checks=0;System.Action<bool,string> check=(ok,label)=>{if(!ok)throw new System.Exception(label);checks++;};var cameraObject=new GameObject("Review camera");cameraObject.transform.SetParent(fixture.transform,false);var cam=cameraObject.AddComponent<Camera>();cam.enabled=false;cam.stereoTargetEye=StereoTargetEyeMask.None;cam.clearFlags=CameraClearFlags.Skybox;cam.fieldOfView=36;cam.nearClipPlane=.02f;cam.farClipPlane=250;var rt=new RenderTexture(1800,1000,24);rt.Create();var tex=new Texture2D(1800,1000,TextureFormat.RGB24,false);var oldRT=RenderTexture.active;
try{
 int[] kinds={0,1,2,3,5,6,7,8};
 for(int slot=0;slot<kinds.Length;slot++){
 int kind=kinds[slot];var a=view.CreateAvatar(kind,null,fixture.transform);a.root.position=new Vector3((slot%4-1.5f)*1.5f,0,slot/4*3);var anim=a.preset.GetComponent<Animator>();anim.cullingMode=AnimatorCullingMode.AlwaysAnimate;anim.Rebind();anim.Play("Idle",0,0);anim.Update(.001f);var hand=a.preset.GetComponentsInChildren<Transform>().First(x=>x.name=="hand.l"||x.name=="Hand_L");var handStart=hand.position;var f=new Staredown.Fighter{id=slot,bot=false,left=.25f,right=.75f,presenceAt=0,presence=new Staredown.StarePresenceFrame{headTracked=true,head=Quaternion.Euler(0,15,0),mouth=.7f,left=new Staredown.StareHandPose{tracked=true,position=new Vector3(-.3f,-.4f,.25f),rotation=Quaternion.identity},right=new Staredown.StareHandPose{tracked=true,position=new Vector3(.3f,-.4f,.25f),rotation=Quaternion.identity}}};var state=new Staredown.ArenaState{clock=0};a.eyes.Set(0,0,0,0);float openL=a.eyes.left.localScale.y,openR=a.eyes.right.localScale.y;a.presence.Observe(f,state,false);
 for(int i=0;i<20;i++){anim.Update(.02f);a.presence.SendMessage("LateUpdate");}
 check((hand.position-handStart).magnitude>.01f,"Tracked arm changes hand position "+kind);check(!float.IsNaN(hand.rotation.w),"Finite tracked hand rotation "+kind);check(Mathf.Abs(a.eyes.left.localScale.y/openL-.75f)<.01f,"Left proportional eyelid "+kind);check(Mathf.Abs(a.eyes.right.localScale.y/openR-.25f)<.01f,"Right proportional eyelid "+kind);check(a.presence.MouthTransform!=null&&a.presence.MouthTransform.gameObject.activeSelf,"Talking mouth "+kind);check(!float.IsNaN(a.presence.MouthTransform.position.x),"Finite mouth "+kind);
 var lod=a.preset.GetComponent<LODGroup>();foreach(var level in lod.GetLODs())foreach(var renderer in level.renderers){if(renderer.name.Contains("Helmet")||renderer.name.Contains("Hat")||renderer.name.Contains("Cape")){var skin=renderer as SkinnedMeshRenderer;check(skin!=null&&skin.bones.All(b=>b!=null),"Rigged attachment "+kind+" "+renderer.name);if(renderer.name.Contains("Helmet")||renderer.name.Contains("Hat"))check(skin.bones.Any(b=>b.name=="head"),"Headgear shares animated head "+kind);}}
 }
 cam.transform.position=new Vector3(0,2.3f,-8);cam.transform.LookAt(new Vector3(0,1.3f,1));cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1800,1000),0,0);tex.Apply();System.IO.File.WriteAllBytes(imagePath,tex.EncodeToPNG());return checks+" runtime eye, mouth and attachment checks passed";
}finally{RenderTexture.active=oldRT;cam.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(tex);UnityEngine.Object.Destroy(fixture);}

}
}
